import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
import type { Hono } from "hono";

/** Exports generated by Vite for rendering with built asset URLs and CSS Modules. */
interface BuiltModule {
    /**
     * Creates the page application from the saved HTML template.
     *
     * @param templatePath - Saved Vite HTML template.
     * @returns The application ready to render requests.
     * @rejects If the template cannot be read.
     */
    createBuiltApp(templatePath: string): Promise<Hono>;
}

/**
 * Validates the dynamically imported render bundle.
 *
 * @param value - Render bundle exports.
 * @returns Whether the built application factory is available.
 */
function isBuiltModule(value: unknown): value is BuiltModule {
    return (
        typeof value === "object" &&
        value !== null &&
        "createBuiltApp" in value &&
        typeof value.createBuiltApp === "function"
    );
}

/**
 * Loads the generated renderer for the source server entrypoint or static exporter.
 *
 * @param outputDirectory - Absolute build output directory.
 * @returns The Hono page application using the built HTML template.
 * @rejects If the render bundle or template is missing or invalid.
 */
export async function loadBuiltApp(outputDirectory: string): Promise<Hono> {
    const module: unknown = await import(pathToFileURL(resolve(outputDirectory, "server/app.js")).href);
    if (!isBuiltModule(module)) {
        throw new Error("Run the landing build first; its server bundle must export createBuiltApp.");
    }
    return module.createBuiltApp(resolve(outputDirectory, "server/index.html"));
}
